import net.minecraft.world.item.Item;
import net.minecraft.world.level.ItemLike;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public final class VillagerInteractionRegistries {
    private static final Logger LOGGER = LoggerFactory.getLogger(VillagerInteractionRegistries.class);

    private VillagerInteractionRegistries() {
    }

    public static void registerCollectable(ItemLike item) {
        Objects.requireNonNull(item.m_5456_(), "Item cannot be null!");
        VillagerInteractionRegistries.getCollectableRegistry().add(item.m_5456_());
    }

    public static void registerCompostable(ItemLike item) {
        Objects.requireNonNull(item.m_5456_(), "Item cannot be null!");
        VillagerInteractionRegistries.getCompostableRegistry().add(item.m_5456_());
    }

    public static void registerFood(ItemLike item, int foodValue) {
        Objects.requireNonNull(item.m_5456_(), "Item cannot be null!");
        Integer oldValue = VillagerInteractionRegistries.getFoodRegistry().put(item.m_5456_(), foodValue);
        if (oldValue != null) {
            LOGGER.info("Overriding previous food value of {}, was: {}, now: {}", new Object[]{item.m_5456_().toString(), oldValue, foodValue});
        }
    }

    public static void registerGiftLootTable(VillagerProfession profession, ResourceLocation lootTable) {
        Objects.requireNonNull(profession, "Profession cannot be null!");
        Objects.requireNonNull(lootTable, "Loot table identifier cannot be null!");
        ResourceLocation oldValue = GiveGiftsToHeroTaskAccessor.fabric_getGifts().put(profession, lootTable);
        if (oldValue != null) {
            LOGGER.info("Overriding previous gift loot table of {} profession, was: {}, now: {}", new Object[]{profession.f_35600_(), oldValue, lootTable});
        }
    }

    private static Set<Item> getCollectableRegistry() {
        return ImmutableCollectionUtils.getAsMutableSet(VillagerEntityAccessor::fabric_getGatherableItems, VillagerEntityAccessor::fabric_setGatherableItems);
    }

